sys_script_fix.script:
(function executeRule(current, previous /*null when async*/ ) {

    var parRec = 'c0ca512c4761f950020ba9f8536d4337'; //Demand Record
    var asmtRec = '7fca11ec4761f950020ba9f8536d4344'; //Assessment Record
    var metType = 'Demand Assessment'; //Metric name
    var subBy = 'Marcus Mathew';

    var parent_record = new GlideRecord('dmn_demand');
    if (parent_record.get(parRec)) {
        var workNotes = '';
        var survey_response = new GlideRecord('asmt_metric_result');
        survey_response.addQuery('instance', asmtRec);
        survey_response.query();
        while (survey_response.next()) {

            workNotes += '<style> table, th, td {border: 1px solid black;border-collapse: collapse;background-color:lightyellow;padding:2px;text-align: left;}</style><table style="width:100%">';

            // Assuming assessment responses are stored in the "Question" field
            workNotes += '<tr style="height: 50.4px;"><td style="width: 500px; height: 15.4px;"><strong>' + survey_response.instance_question.getDisplayValue() + '</strong></td>' + '<td style="text-align: center; "width: 700px; height: 15.4px;"">' + survey_response.string_value + '</td>';

            // End the table
            workNotes += '</table>';

        }

        parent_record.work_notes = '[code]' +
            '<p style="text-align: center;"><span style="font-size: 14pt;"><strong>' + metType + " " + '</strong>(<em><span style="font-size: 10pt;">Submitted by: <strong>' + subBy + '</strong></span></em>)</span></p>' +
            '<table style="border-collapse: collapse; width: 100.05%; height: 30.4px; border-color: #000000; border-style: solid;" border="1"><tbody><tr style="height: 30.4px;"><td style="width: 60.6755%; height: 30.4px; text-align: center;"><span style="font-size: 10pt;"><strong>Assessment Question</strong></span></td><td style="width: 35.3009%; height: 30.4px; text-align: center;"><span style="font-size: 10pt;"><strong>Response</strong></span></td></tr></tbody></table>' + '</strong></span></p>' + workNotes + '[/code]';
        parent_record.update();
    }



})(current, previous);
